// Generated by Kukicha (requires Go 1.27+)

// Per-key sliding-window failure budget on top of Do. When the budget is
// exhausted the circuit "opens": further DoBudget calls return CircuitOpen
// immediately instead of looping. Budget state lives in process memory.
//
// Example:
//
//	budget := retry.NewBudget()
//	    |> retry.WithLimit(3, 5 * time.Minute)
//	    |> retry.WithKey(alert.workload)
//
//	outcome := retry.DoBudget(budget, cfg, () => shell.Check("kubectl", "rollout", "restart"))
//	if outcome is retry.CircuitOpen
//	    return Escalated{reason: "circuit open"}
package retry

import (
	ctxpkg "kukicha.org/kukicha/stdlib/ctx"
	"kukicha.org/kukicha/stdlib/datetime"
	"sync"
	"time"
)

// BudgetResult is the outcome of a DoBudget call. Succeeded means fn ran and
// passed (the key's failure log is cleared); CircuitOpen means the budget for
// this key was exhausted before fn was invoked — nothing ran this call;
// Failed means fn ran but every attempt errored, Err carries the last error,
// and the failure is recorded against the key. Circuit state and operation
// outcome are distinct arms so callers branch exhaustively instead of
// matching an error sentinel with errors.Is.
type BudgetResult interface{ isBudgetResult() }

type Succeeded struct{}

func (Succeeded) isBudgetResult() {}

type CircuitOpen struct{}

func (CircuitOpen) isBudgetResult() {}

type Failed struct {
	Err error
}

func (Failed) isBudgetResult() {}

// budgetState holds the shared per-key failure log behind a mutex. Stored
// behind a reference so copies of Budget (from the builder chain) share it.
type budgetState struct {
	mu       sync.Mutex
	failures map[string][]datetime.Time
}

// Budget describes a sliding-window failure budget. Build via NewBudget +
// WithLimit + WithKey; pass to DoBudget.
type Budget struct {
	Key         string
	MaxFailures int
	Window      datetime.Duration
	state       *budgetState
}

// NewBudget creates a Budget with defaults (3 failures in 1 minute, empty
// key). Reuse a single Budget across calls — the failure log is in its
// shared state.
func NewBudget() Budget {
	s := budgetState{failures: map[string][]datetime.Time{}}
	return Budget{Key: "", MaxFailures: 3, Window: time.Minute, state: &s}
}

// WithLimit sets the failure count + sliding window. Window is a
// time.Duration so callers write `5 * time.Minute` etc.
func WithLimit(b Budget, maxFailures int, window datetime.Duration) Budget {
	b.MaxFailures = maxFailures
	b.Window = window
	return b
}

// WithKey selects which keyed budget bucket DoBudget records into. Use the
// action target (workload, host, queue) so retries on action A don't trip
// the breaker on unrelated action B.
func WithKey(b Budget, key string) Budget {
	b.Key = key
	return b
}

// Open reports whether the circuit is currently open (over budget) for
// this budget's key. Use to short-circuit other work; DoBudget already
// checks this internally.
func Open(b Budget) bool {
	b.state.mu.Lock()
	defer b.state.mu.Unlock()
	pruneLocked(b)
	return len(b.state.failures[b.Key]) >= b.MaxFailures
}

// DoBudget runs fn under cfg's retry policy, but only if the budget for
// this key isn't exhausted. Success clears the key's failure log; failure
// appends one entry to it. Returns CircuitOpen when the circuit is open —
// fn is not invoked on that path.
func DoBudget(b Budget, cfg Config, fn func() error) BudgetResult {
	if Open(b) {
		return CircuitOpen{}
	}
	err := Do(cfg, fn)
	record(b, err)
	if err == nil {
		return Succeeded{}
	}
	return Failed{Err: err}
}

// DoBudgetCtx is DoBudget with a deadline: retries stop when the context is
// cancelled or its deadline passes. A context cancellation or deadline
// exhaustion is returned as Failed{Err} but is NOT recorded against the
// budget — the caller pulled the plug, the workload didn't fail. (An fn
// that itself returns the context's error is indistinguishable and will be
// recorded.)
// The handle type is inferred, so inline lambdas work:
//
//	retry.DoBudgetCtx(budget, h, cfg, (h) => pollOnce(h))
func DoBudgetCtx(b Budget, h ctxpkg.Handle, cfg Config, fn func(ctxpkg.Handle) error) BudgetResult {
	if Open(b) {
		return CircuitOpen{}
	}
	err := DoCtx(h, cfg, fn)
	if err != nil && err == h.Ctx.Err() {
		return Failed{Err: err}
	}
	record(b, err)
	if err == nil {
		return Succeeded{}
	}
	return Failed{Err: err}
}

// Reset clears the key's failure log so the next DoBudget invokes fn again —
// the half-open probe step for a circuit that has been open long enough.
// Example: retry.Reset(budget)  # let one probe through
func Reset(b Budget) {
	b.state.mu.Lock()
	defer b.state.mu.Unlock()
	delete(b.state.failures, b.Key)
}

// record appends a failure timestamp or clears on success.
func record(b Budget, err error) {
	b.state.mu.Lock()
	defer b.state.mu.Unlock()
	if err == nil {
		delete(b.state.failures, b.Key)
		return
	}
	pruneLocked(b)
	b.state.failures[b.Key] = append(b.state.failures[b.Key], datetime.Now())
}

// pruneLocked drops timestamps older than the window. Caller must hold mu.
func pruneLocked(b Budget) {
	now := datetime.Now()
	kept := []datetime.Time{}
	for _, t := range b.state.failures[b.Key] {
		if now.Sub(t) < b.Window {
			kept = append(kept, t)
		}
	}
	b.state.failures[b.Key] = kept
}
